CREATE PROCEDURE cancel_order(p_order_id integer, OUT p_rows integer)
LANGUAGE plpgsql
AS $$
BEGIN
  UPDATE orders
     SET status = 'cancelled'
   WHERE order_id = p_order_id
     AND status = 'new';
  GET DIAGNOSTICS p_rows = ROW_COUNT;
END;
$$;

DO $$
DECLARE
  v_rows integer;
BEGIN
  CALL cancel_order(5, v_rows);
  RAISE NOTICE 'rows changed: %', v_rows;
END;
$$;

CREATE PROCEDURE archive_orders(p_before date, p_batch integer DEFAULT 2)
LANGUAGE plpgsql
AS $$
DECLARE
  v_moved integer;
BEGIN
  LOOP
    WITH moved AS (
      DELETE FROM orders
       WHERE order_id IN (SELECT order_id
                            FROM orders
                           WHERE order_date < p_before
                           ORDER BY order_id
                           LIMIT p_batch)
      RETURNING *
    )
    INSERT INTO orders_archive SELECT * FROM moved;

    GET DIAGNOSTICS v_moved = ROW_COUNT;
    EXIT WHEN v_moved = 0;

    COMMIT;
    RAISE NOTICE 'committed a batch of % rows', v_moved;
  END LOOP;
END;
$$;

CREATE FUNCTION archive_orders_fn(p_before date)
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
  v_moved integer;
BEGIN
  DELETE FROM orders WHERE order_date < p_before;
  GET DIAGNOSTICS v_moved = ROW_COUNT;
  COMMIT;
  RETURN v_moved;
END;
$$;

SELECT archive_orders_fn('2026-10-10');

